draw(A--P--D);
draw(P--B);
draw(P--C);
draw(arc(P,0.3,degrees(A - P),degrees(C - P)),red);
draw(arc(P,0.5,degrees(B - P),degrees(D - P)),red);
draw(arc(P,0.6,degrees(B - P),degrees(C - P)),red);
draw(arc(P,0.9,degrees(A - P),degrees(D - P)),red);

label("$A$", A, SW);
label("$B$", B, S);
label("$C$", C, S);
